    edges = s.get('neighbors') or []
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    first = 0.0
    second = 0.0
    amount = 0.0
    for i in range(len(sites)):
        if radii[i] <= 0:
            continue
        oi = sites[i].get('occupancy')
        oi = 1.0 if oi is None else max(0.0, oi)
        if oi <= 0:
            continue
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= len(sites) or d <= 0 or radii[j] <= 0:
                continue
            oj = sites[j].get('occupancy')
            oj = 1.0 if oj is None else max(0.0, oj)
            coordination += oj * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        first += oi * coordination
        second += oi * coordination ** 2
        amount += oi
    if amount <= 0 or first <= 0:
        return 0.0
    mean = first / amount
    return float(max(0.0, second / amount - mean ** 2) ** 0.5 / mean)

