def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    if n == 0 or not edges:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    adjacency = [[] for a in sites]
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        image = edge.get('image')
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or occ[i] <= 0 or occ[j] <= 0:
            continue
        if image is None or len(image) != 3:
            continue
        if d <= 1.20 * (radii[i] + radii[j]):
            adjacency[i] = adjacency[i] + [(j, image)]
    visited = [False] * n
    shifts = [[0, 0, 0] for a in sites]
    total = 0.0
    amount = sum(occ[i] for i in range(n) if radii[i] > 0)
    for root in range(n):
        if visited[root] or occ[root] <= 0 or radii[root] <= 0:
            continue
        queue = [root]
        visited[root] = True
        finite = True
        component_weight = 0.0
        for step in range(n):
            if step >= len(queue):
                break
            i = queue[step]
            component_weight += occ[i]
            for j, image in adjacency[i]:
                candidate = [shifts[i][k] + image[k] for k in range(3)]
                if not visited[j]:
                    visited[j] = True
                    shifts[j] = candidate
                    queue = queue + [j]
                elif any(shifts[j][k] != candidate[k] for k in range(3)):
                    finite = False
        if finite:
            total += component_weight
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    chi = [0.0] * n
    hardness = [0.0] * n
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and ion > 0 and ion > affinity:
            chi[i] = 0.5 * (ion + affinity)
            hardness[i] = ion - affinity
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or hardness[i] <= 0 or hardness[j] <= 0:
            continue
        w = occ[i] * occ[j] * (max(0.0, 1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2
        relaxation = (chi[i] - chi[j]) ** 2 / (2.0 * (hardness[i] + hardness[j]))
        total += w * relaxation
    return float(total / (2.0 * amount))

